  assert.equal(ui.tasks[0].due_date, '2024-02-29');
  assert.deepEqual(ui.titles(), ['Renamed']);
  assert.equal(completion.value, 'Open');
  assert.equal(priority.value, 'High');
  due.value = '   ';
